      <section class="stats-card stats-small-card stats-ports-card"><span class="stats-icon-tile">${ot("pin")}</span><div>${ge(r.uniquePorts)}<h2>ports on your map</h2><p>${ft(r.portCalls)} itinerary port visits. Hello again, horizon.</p></div>${ia("stats-small-sparkle")}</section>
